<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, idempotencyKey } from '../api/http'
const tab=ref('assessments'), assessments=ref<any[]>([]), wrong=ref<any[]>([]), appeals=ref<any[]>([]), mastery=ref<any[]>([]), directions=ref<any[]>([]), diag=reactive({directionId:undefined as string|undefined,durationMinutes:30,difficulty:3}), taking=ref(false), detail=ref<any>(), attempt=ref<any>(), answers=reactive<Record<number,any>>({}), result=ref<any>(), submitting=ref(false)
async function load(){const [a,w,p,m,profile]=await Promise.all([api<any>({url:'/assessments',params:{pageSize:100}}),api<any[]>({url:'/wrong-questions'}),api<any[]>({url:'/assessment-appeals'}),api<any[]>({url:'/mastery'}),api<any>({url:'/profiles/me'}).catch(()=>null)]);assessments.value=a.items;wrong.value=w;appeals.value=p;mastery.value=m;directions.value=(profile?.directions||[]).filter((x:any)=>x.directionId!=null).map((x:any)=>({id:String(x.directionId),name:x.name,primary:x.primary}));if(!diag.directionId){const primary=directions.value.find(x=>x.primary)||directions.value[0];diag.directionId=primary?.id}}
onMounted(load)
async function diagnostic(){try{const a=await api<any>({method:'POST',url:'/diagnostics',data:diag,silent:true});await begin(a);await load()}catch(e:any){const msg=e?.response?.data?.message||e?.response?.data?.error?.message||'';if(msg.includes('暂无可用诊断题')){ElMessageBox.alert('该方向目前还没有可用的题目，暂时无法生成诊断。请换一个方向试试，或联系管理员补充题库。','暂无诊断题目',{confirmButtonText:'知道了',type:'warning'})}else{ElMessage.error(msg||'诊断生成失败，请稍后重试')}}}
async function begin(a:any){detail.value=await api<any>({url:`/assessments/${a.publicId}`});attempt.value=await api<any>({method:'POST',url:`/assessments/${a.publicId}/attempts`});result.value=undefined;Object.keys(answers).forEach(k=>delete answers[Number(k)]);taking.value=true}
async function resume(a:any){detail.value=await api<any>({url:`/assessments/${a.publicId}`});const r=await api<any>({url:`/attempts/${a.lastAttemptPublicId}/result`});attempt.value=r.attempt;result.value=undefined;Object.keys(answers).forEach(k=>delete answers[Number(k)]);for(const x of r.answers)answers[x.sequence]=x.answer;taking.value=true}
async function viewResult(a:any){detail.value=await api<any>({url:`/assessments/${a.publicId}`});result.value=await api<any>({url:`/attempts/${a.lastAttemptPublicId}/result`});attempt.value=result.value.attempt;taking.value=true}
async function saveAnswer(sequence:number){await api({method:'PUT',url:`/attempts/${attempt.value.publicId}/answers/${sequence}`,data:{answer:answers[sequence]}})}
async function waitForGrading(){for(let i=0;i<90;i++){result.value=await api<any>({url:`/attempts/${attempt.value.publicId}/result`});if(!['SUBMITTED','GRADING'].includes(result.value.attempt.status))return;await new Promise(resolve=>window.setTimeout(resolve,1000))}throw new Error('批改仍在后台进行，请稍后重新打开结果')}
async function submit(){submitting.value=true;try{for(let i=0;i<detail.value.questions.length;i++)if(answers[i+1]!==undefined)await saveAnswer(i+1);await api({method:'POST',url:`/attempts/${attempt.value.publicId}/submission`,headers:{'Idempotency-Key':idempotencyKey()}});await waitForGrading();if(result.value.attempt.status==='GRADED')ElMessage.success('已交卷，批改和掌握度更新完成');else ElMessage.warning('客观题已批改，部分主观题等待重试');await load()}catch(e:any){ElMessage.error(e?.response?.data?.error?.message||e?.response?.data?.message||'交卷失败，请稍后重试')}finally{submitting.value=false}}
async function retryGrading(){submitting.value=true;try{await api({method:'POST',url:`/attempts/${attempt.value.publicId}/grading-retry`});await waitForGrading();await load()}finally{submitting.value=false}}
async function correctWrong(row:any){await api({method:'POST',url:`/wrong-questions/${row.id}/correction`,data:{reasonCode:row.aiReasonCode||'OTHER'}});ElMessage.success('已标记为完成订正');await load()}
async function appealAnswer(row:any){const reason=await ElMessageBox.prompt('说明你认为评分需要复核的原因','提交评分申诉',{inputValidator:(value)=>Boolean(value?.trim())||'请填写申诉原因'}).then(value=>value.value);await api({method:'POST',url:`/attempt-answers/${row.answerId}/appeals`,data:{reason,evidence:{gradingVersion:row.gradingHistory?.[0]?.version}}});ElMessage.success('申诉已提交，可在申诉记录查看进度');await load()}
async function withdrawAppeal(row:any){await api({method:'POST',url:`/assessment-appeals/${row.publicId}/withdrawal`});await load()}
function options(q:any){return q.options||[]}
</script>
<template><div><div class="page-head"><div><h2>评估是校准，不是评判</h2><p>诊断结果、练习表现、项目证据与间隔复习共同形成掌握度；自评置信度上限为 0.2。</p></div></div><div class="diagnostic panel"><div><span class="eyebrow">QUICK DIAGNOSTIC</span><h3>生成一次自适应诊断</h3><p>从公共题库抽取与你方向和难度匹配的题目。</p></div><el-select v-model="diag.directionId"><el-option v-for="d in directions" :key="d.id" :value="String(d.id)" :label="d.name"/></el-select><el-select v-model="diag.difficulty"><el-option v-for="n in 5" :key="n" :value="n" :label="`难度 ${n}`"/></el-select><el-button type="primary" :disabled="!diag.directionId" @click="diagnostic">生成诊断并开始</el-button></div><section class="panel assessment-panel"><el-tabs v-model="tab"><el-tab-pane label="评估记录" name="assessments"><el-table :data="assessments"><el-table-column prop="title" label="评估" min-width="260"/><el-table-column prop="type" label="类型" width="120"/><el-table-column prop="durationMinutes" label="时长" width="100"/><el-table-column prop="passScore" label="通过分" width="100"/><el-table-column prop="status" label="状态" width="110"/><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="!row.lastAttemptStatus" link type="primary" @click="begin(row)">开始</el-button><el-button v-else-if="row.lastAttemptStatus==='IN_PROGRESS'" link type="primary" @click="resume(row)">继续</el-button><el-button v-else-if="row.lastAttemptStatus==='EXPIRED'" link disabled>已超时</el-button><el-button v-else link type="primary" @click="viewResult(row)">查看结果</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane :label="`错题本 ${wrong.length}`" name="wrong"><el-table :data="wrong"><el-table-column prop="id" label="记录编号"/><el-table-column prop="wrongCount" label="错误次数"/><el-table-column prop="lastWrongAt" label="最近错误"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status!=='RESOLVED'" link type="primary" @click="correctWrong(row)">完成订正</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane :label="`申诉记录 ${appeals.length}`" name="appeals"><el-table :data="appeals"><el-table-column prop="createdAt" label="提交时间"/><el-table-column prop="reason" label="原因"/><el-table-column prop="status" label="状态"/><el-table-column prop="resolution" label="处理结果"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='PENDING'" link @click="withdrawAppeal(row)">撤回</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="知识掌握度" name="mastery"><div v-if="!mastery.length" class="empty">完成诊断或学习任务后生成掌握度证据</div><div v-for="m in mastery" :key="m.knowledgePointId" class="mastery"><div><b>知识点 #{{m.knowledgePointId}}</b><small>{{m.level}} · {{m.evidenceCount}} 条证据</small></div><el-progress :percentage="Math.round(Number(m.score))" :stroke-width="9"/><span>置信度 {{Math.round(Number(m.confidence)*100)}}%</span></div></el-tab-pane></el-tabs></section><el-dialog v-model="taking" :title="detail?.assessment?.title||'在线评估'" width="760" :close-on-click-modal="false"><template v-if="!result"><div v-for="(q,i) in detail?.questions" :key="i" class="question"><b>{{i+1}}. {{q.stem}}</b><el-radio-group v-if="options(q).length" v-model="answers[i+1]" class="options" @change="saveAnswer(i+1)"><el-radio v-for="(o,n) in options(q)" :key="n" :value="String.fromCharCode(65+n)">{{String.fromCharCode(65+n)}}. {{o}}</el-radio></el-radio-group><el-input v-else v-model="answers[i+1]" type="textarea" :rows="3" @blur="saveAnswer(i+1)"/></div><div class="submit-row"><span class="muted">答案实时保存；交卷操作具有幂等保护</span><el-button type="primary" :loading="submitting" @click="submit">确认交卷</el-button></div></template><template v-else><div class="result"><span>{{result.attempt.totalScore??0}}</span><h3>本次评估已完成</h3><p>状态 {{result.attempt.status}} · 及格线 {{detail.assessment.passScore}}</p><el-button v-if="['PARTIALLY_GRADED','GRADING_FAILED'].includes(result.attempt.status)" type="primary" :loading="submitting" @click="retryGrading">重试未完成批改</el-button><el-table :data="result.answers"><el-table-column prop="sequence" label="#" width="60"/><el-table-column label="得分" width="100"><template #default="{row}">{{row.score??0}} / {{row.maxScore}}</template></el-table-column><el-table-column prop="feedback" label="批改反馈" min-width="180"/><el-table-column prop="analysis" label="解析" min-width="180"/><el-table-column label="批改版本" width="100"><template #default="{row}">{{row.gradingHistory?.length||0}}</template></el-table-column><el-table-column label="复核" width="90"><template #default="{row}"><el-button link :disabled="row.gradingStatus!=='GRADED'" @click="appealAnswer(row)">申诉</el-button></template></el-table-column></el-table></div></template></el-dialog></div></template>
<style scoped>.diagnostic{display:grid;grid-template-columns:1fr 190px 130px auto;gap:15px;align-items:center;background:#173d31;color:white;margin-bottom:18px}.diagnostic h3{margin:7px 0}.diagnostic p{color:#bcd0c6;font-size:12px;margin:0}.assessment-panel{min-height:440px}.mastery{display:grid;grid-template-columns:190px 1fr 100px;align-items:center;gap:20px;border-top:1px solid var(--line);padding:15px}.mastery b,.mastery small{display:block}.mastery small,.mastery>span{font-size:10px;color:var(--muted)}.question{padding:18px 4px;border-bottom:1px solid var(--line)}.options{display:flex;flex-direction:column;align-items:start;margin-top:14px;gap:7px}.submit-row{display:flex;justify-content:space-between;align-items:center;margin-top:20px}.result{text-align:center}.result>span{font:54px 'DM Serif Display';color:var(--green)}@media(max-width:800px){.diagnostic{grid-template-columns:1fr}.mastery{grid-template-columns:1fr}}</style>
